using System;
using Arena.Sim;
using NUnit.Framework;

namespace Arena.Tests.FixedMath;

public class DeterministicRandomTests
{
    [Test]
    public void SeedZeroMatchesOriginalCGoldenSequence()
    {
        // Independently compiled Vigna's unsigned C algorithm; not generated by the production C# class.
        ulong[] expected =
        {
            0xE220A8397B1DCDAFUL, 0x6E789E6AA1B965F4UL,
            0x06C45D188009454FUL, 0xF88BB8A8724C81ECUL,
            0x1B39896A51A8749BUL, 0x53CB9F0C747EA2EAUL,
            0x2C829ABE1F4532E1UL, 0xC584133AC916AB3CUL,
        };
        var random = new DeterministicRandom(0);
        foreach (ulong value in expected)
            Assert.That(random.NextUInt64(), Is.EqualTo(value));
        Assert.That(random.State, Is.EqualTo(unchecked(8UL * 0x9E3779B97F4A7C15UL)));
    }

    [TestCase(0UL)]
    [TestCase(1UL)]
    [TestCase(ulong.MaxValue)]
    public void ValueCopyAndStateRestoreContinueTheSameSequence(ulong seed)
    {
        var first = new DeterministicRandom(seed);
        for (int i = 0; i < 17; i++) first.NextUInt64();
        var copy = first;
        var restored = new DeterministicRandom(first.State);
        ulong original = first.State;
        copy.NextUInt64();
        Assert.That(first.State, Is.EqualTo(original), "copy must not share state");
        copy = first;
        for (int i = 0; i < 1000; i++)
        {
            ulong value = first.NextUInt64();
            Assert.That(copy.NextUInt64(), Is.EqualTo(value));
            Assert.That(restored.NextUInt64(), Is.EqualTo(value));
        }
    }

    [Test]
    public void DefaultValueIsTheZeroSeed()
    {
        var random = default(DeterministicRandom);
        Assert.That(random.NextUInt64(), Is.EqualTo(0xE220A8397B1DCDAFUL));
    }

    [TestCase(0)]
    [TestCase(-1)]
    public void InvalidBoundThrowsWithoutConsumingState(int bound)
    {
        var random = new DeterministicRandom(42);
        Assert.Throws<ArgumentOutOfRangeException>(() => random.NextInt(bound));
        Assert.That(random.State, Is.EqualTo(42UL));
    }

    [Test]
    public void RejectionSamplingRejectsAZeroOutputForBoundThree()
    {
        // state + gamma = 0 produces output 0, below 2^64 % 3 = 1.
        var random = new DeterministicRandom(0x61C8864680B583EBUL);
        Assert.That(random.NextInt(3), Is.EqualTo(1), "next accepted C golden output modulo 3");
        Assert.That(random.State, Is.EqualTo(0x9E3779B97F4A7C15UL), "must consume two samples");
    }

    [TestCase(1)]
    [TestCase(2)]
    [TestCase(3)]
    [TestCase(17)]
    [TestCase(int.MaxValue)]
    public void BoundedOutputIsInRangeAndReproducible(int bound)
    {
        var first = new DeterministicRandom(ulong.MaxValue);
        var second = first;
        for (int i = 0; i < 10_000; i++)
        {
            int value = first.NextInt(bound);
            if (value < 0 || value >= bound) Assert.Fail($"bound={bound}, value={value}");
            Assert.That(second.NextInt(bound), Is.EqualTo(value));
        }
    }
}
